parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "fatura_no": {
      "type": "string",
      "description": "Fatura numarası, okunamıyorsa 'OKUNAMADI'"
    },
    "fatura_tarihi": {
      "type": "string",
      "description": "Fatura tarihi, okunamıyorsa 'OKUNAMADI'"
    },
    "satici_unvani": {
      "type": "string",
      "description": "Satıcı firma unvanı, okunamıyorsa 'OKUNAMADI'"
    },
    "satici_vkn": {
      "type": "string",
      "description": "Satıcı VKN, okunamıyorsa 'OKUNAMADI'"
    },
    "satici_vergi_dairesi": {
      "type": ["string", "null"],
      "description": "Faturada yoksa null"
    },
    "satici_adresi": {
      "type": ["string", "null"],
      "description": "Faturada yoksa null"
    },
    "alici_unvani": {
      "type": "string",
      "description": "Alıcı firma unvanı, okunamıyorsa 'OKUNAMADI'"
    },
    "alici_vkn": {
      "type": "string",
      "description": "Alıcı VKN, okunamıyorsa 'OKUNAMADI'"
    },
    "para_birimi": {
      "type": "string",
      "description": "Örn: TRY, USD, EUR"
    },
    "doviz_kuru": {
      "type": ["number", "null"],
      "description": "Faturada yoksa null"
    },
    "matrah": {
      "type": "number",
      "description": "KDV hariç toplam tutar"
    },
    "kdv_orani": {
      "type": "string",
      "description": "Faturada yazan gerçek oran, örn: '%20', '%10', '%1'"
    },
    "kdv_tutari": {
      "type": "number"
    },
    "genel_toplam": {
      "type": "number"
    },
    "odeme_sekli": {
      "type": "string",
      "description": "Örn: Nakit, Kredi Kartı, Havale/EFT, Çek"
    },
    "vade_tarihi": {
      "type": ["string", "null"],
      "description": "Faturada yoksa null"
    },
    "irsaliye_no": {
      "type": ["string", "null"],
      "description": "Faturada yoksa null"
    },
    "ettn": {
      "type": ["string", "null"],
      "description": "e-Fatura/e-Arşiv Evrensel Tekil Tanımlama Numarası, faturada yoksa null"
    },
    "gider_kategorisi": {
      "type": "string",
      "enum": ["Kira", "Yakıt", "Danışmanlık", "Ofis Malzemesi", "Yazılım/Abonelik", "Nakliye", "Diğer"],
      "description": "Ürün/hizmet açıklamasına göre en uygun kategori"
    },
    "kalemler": {
      "type": "array",
      "description": "Fatura kalem satırları",
      "items": {
        "type": "object",
        "properties": {
          "aciklama": {
            "type": "string"
          },
          "miktar": {
            "type": "number"
          },
          "birim_fiyat": {
            "type": "number"
          },
          "kdv_orani": {
            "type": "string"
          },
          "tutar": {
            "type": "number"
          }
        },
        "required": ["aciklama", "miktar", "birim_fiyat", "kdv_orani", "tutar"],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "fatura_no",
    "fatura_tarihi",
    "satici_unvani",
    "satici_vkn",
    "alici_unvani",
    "alici_vkn",
    "para_birimi",
    "matrah",
    "kdv_orani",
    "kdv_tutari",
    "genel_toplam",
    "odeme_sekli",
    "gider_kategorisi",
    "kalemler"
  ],
  "additionalProperties": false
}
